struct OpenVault{vault:Mutex<Vault>,_lock:std::fs::File,cookie:u64,active:AtomicBool,commit_gate:Mutex<()>}
pub struct Protected {open:Mutex<HashMap<String,Arc<OpenVault>>>,running:Mutex<HashSet<String>>,cancelled:Mutex<HashSet<String>>,progress:Mutex<HashMap<String,Value>>,errors:Mutex<HashMap<String,(String,String)>>,fingerprints:Mutex<HashMap<String,String>>,counter:AtomicU64}
