 pub fn new()->Self{Self{open:Mutex::new(HashMap::new()),running:Mutex::new(HashSet::new()),cancelled:Mutex::new(HashSet::new()),progress:Mutex::new(HashMap::new()),errors:Mutex::new(HashMap::new()),fingerprints:Mutex::new(HashMap::new()),counter:AtomicU64::new(1)}}
 pub fn is_protected_dir(dir:&Path)->bool{if dir.is_symlink()||!dir.is_dir(){return false}dir.join(".atlas-protected").symlink_metadata().is_ok()||dir.join("workspace.atlas").symlink_metadata().is_ok()}
 pub fn is_protected(root:&Path,default:&Path,id:&str)->bool{(id=="default"||valid_id(id))&&Self::is_protected_dir(&crate::workspace_paths::resolve(root,default,id))}
 pub fn create(&self,root:&Path,name:&str,password:&str)->Result<Value,String>{if password.is_empty(){return Err("Укажите пароль".into())}let id=uuid::Uuid::new_v4().simple().to_string();let dir=root.join(&id);std::fs::create_dir(&dir).map_err(|_|"Не удалось создать пространство")?;let result=(||{let vault=Vault::create(&dir.join("workspace.atlas"),password)?;vault.set_workspace_name(name)?;std::fs::write(dir.join(".atlas-protected"),b"atlas-protected-v1").map_err(|_|"Не удалось создать пространство")?;std::fs::write(dir.join(".workspace.json"),json!({"name":name,"protected":true}).to_string()).map_err(|_|"Не удалось создать пространство")?;let lock=lock_workspace(&dir)?;let entry=Arc::new(OpenVault{vault:Mutex::new(vault),_lock:lock,cookie:self.counter.fetch_add(1,Ordering::Relaxed),active:AtomicBool::new(true),commit_gate:Mutex::new(())});self.open.lock().map_err(|_|"Пространство недоступно")?.insert(id.clone(),entry);Ok(json!({"id":id,"name":name,"protected":true}))})();result}
 pub fn unlock(&self,root:&Path,default:&Path,id:&str,password:&str)->Result<Value,String>{if !Self::is_protected(root,default,id){return Err("Пространство недоступно".into())}let dir=crate::workspace_paths::resolve(root,default,id);let lock=lock_workspace(&dir)?;let vault=Vault::open(&dir.join("workspace.atlas"),password).map_err(|e|if e=="Не удалось открыть защищённое пространство"{"Пространство недоступно".to_owned()}else{"Неверный пароль или повреждённый контейнер".to_owned()})?;let metadata=std::fs::read(dir.join(".workspace.json")).ok().and_then(|b|serde_json::from_slice::<Value>(&b).ok());let name=if metadata.as_ref().is_some_and(|v|v["pending_copy_name"]==true){let name=metadata.as_ref().and_then(|v|v["name"].as_str()).filter(|s|!s.trim().is_empty()&&s.chars().count()<=100).ok_or("Неверное название копии")?;vault.set_workspace_name(name)?;name.to_owned()}else{vault.workspace_name()?};std::fs::write(dir.join(".workspace.json"),json!({"name":name,"protected":true}).to_string()).map_err(|_|"Не удалось сохранить название пространства")?;let entry=Arc::new(OpenVault{vault:Mutex::new(vault),_lock:lock,cookie:self.counter.fetch_add(1,Ordering::Relaxed),active:AtomicBool::new(true),commit_gate:Mutex::new(())});self.invalidate(id);self.open.lock().map_err(|_|"Пространство недоступно")?.insert(id.to_owned(),entry);Ok(json!({"id":id,"name":name,"protected":true}))}
 pub fn lock_for_export(&self,dir:&std::fs::File,id:&str,password:&str)->Result<(std::fs::File,std::fs::File),String>{
  if id!="default"&&!valid_id(id){return Err("Пространство недоступно".into())}if self.lookup(id).is_some(){return Err("Закройте защищённое пространство перед сохранением копии".into())}let lock=lock_workspace_fd(dir)?;if self.lookup(id).is_some(){return Err("Закройте защищённое пространство перед сохранением копии".into())}let source=Vault::verify_closed_dir(dir,password)?;Ok((lock,source))
 }
 pub fn rename(&self,root:&Path,default:&Path,id:&str,name:&str)->Result<Value,String>{let name=name.trim();if name.is_empty()||name.chars().count()>100{return Err("Неверное имя".into())}let entry=self.lookup(id).ok_or("Пространство заблокировано")?;let vault=entry.vault.lock().map_err(|_|"Пространство недоступно")?;let _gate=entry.commit_gate.lock().map_err(|_|"Пространство недоступно")?;if !entry.active.load(Ordering::Acquire){return Err("Пространство заблокировано".into())}vault.set_workspace_name(name)?;let dir=crate::workspace_paths::resolve(root,default,id);std::fs::write(dir.join(".workspace.json"),json!({"name":name,"protected":true}).to_string()).map_err(|_|"Не удалось сохранить название пространства")?;Ok(json!({"id":id,"name":name,"protected":true}))}
